#include "KS/SRC/stringx.h"

typedef unsigned int uint32;
typedef unsigned short uint16;
typedef unsigned int u_int;

class nglTexture;
struct nglQuad;

extern void nglSetQuadTex(nglQuad *, nglTexture *);
extern void nglSetQuadMapFlags(nglQuad *, u_int);

enum
{
    NGLMAP_BILINEAR_FILTER = 0x00000002,
    NGLMAP_CLAMP_U = 0x00000010,
    NGLMAP_CLAMP_V = 0x00000020
};

struct PanelMaterial
{
    stringx name;
    uint32 color;
    float emissive;
    float shininess;
    float shinestr;
    bool additive;
    bool hasmap;
    nglTexture *texture;
    bool bilinearfilter;
    bool wrapu;
    bool wrapv;
    stringx filename;
};

class PanelQuad
{
    char padding[0x1c];
    nglQuad *quad_address;

public:
    void setTexture(nglTexture *tex) { nglSetQuadTex((nglQuad *)((char *)this + 0x1c), tex); }
    void setMaterialFlags(u_int mapflags) { nglSetQuadMapFlags((nglQuad *)((char *)this + 0x1c), mapflags); }
};

class vector3d;
class color32;
class vector2d;

class PanelBatch
{
public:
    uint32 material;
    PanelMaterial mat;
    uint32 verttype;
    uint32 color;
    uint16 nwedges;
    PanelQuad *pq;
    vector3d *wedges;
    color32 *colors;
    vector2d *tex;
    uint16 strip_count;
    uint16 index_count;
    uint16 *didxs;

    virtual ~PanelBatch();
    void Reload(PanelMaterial *mats);
};

void PanelBatch::Reload(PanelMaterial* mats)
{
	mat = mats[material];
	u_int mapflags = 0;
	if(mat.hasmap) 
	{
		pq->setTexture(mat.texture);
	}

	if (mat.bilinearfilter) 
	{
		mapflags |= NGLMAP_BILINEAR_FILTER;
	}

	if (!mat.wrapu)
	{
		mapflags |= NGLMAP_CLAMP_U;
	}

	if (!mat.wrapv)
	{
		mapflags |= NGLMAP_CLAMP_V;
	}
	if( mapflags )	
	  pq->setMaterialFlags(mapflags);
}
